/* Main container */
.mainContainer {
  display: flex;
  min-height: 100vh;
  position: relative;
}

/* Sidebar styles */
.sidebar {
  background: #ffffff;
  color: #333;
  height: 100vh;
  position: sticky;
  top: 0;
  left: 0;
  overflow-x: hidden;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  border-right: 1px solid rgba(0, 0, 0, 0.06);
  z-index: 100;
  padding-top: 40px;
}

.sidebar::-webkit-scrollbar {
  width: 5px;
}

.sidebar::-webkit-scrollbar-thumb {
  background: rgba(0, 0, 0, 0.1);
  border-radius: 10px;
}

.sidebar::-webkit-scrollbar-track {
  background: transparent;
}

/* Sidebar header */
.sidebarHeader {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 2px 17px;
  height: 30px;
  margin-top: 26px;
}

.logoContainer {
  display: flex;
  align-items: center;
  overflow: hidden;
}

.logoText {
  font-size: 20px;
  font-weight: 700;
  background: linear-gradient(135deg, #818188, #7f7d85);
  -webkit-background-clip: text;
  background-clip: text;
  margin-left: 10px;
}

.toggleButton {
  width: 36px;
  height: 36px;
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  color: #6366f1;
  background-color: rgba(99, 102, 241, 0.1);
  transition: all 0.2s ease;
}

.toggleButton:hover {
  background-color: rgba(99, 102, 241, 0.15);
}

/* Routes container */
.routesContainer {
  flex: 1;
  flex-direction: column;
  padding: 10px;
  gap: 1px;
  overflow-y: auto;
}

/* Nav link styles */
.navLink,
.mobileNavLink {
  display: flex;
  align-items: center;
  padding: 5px 5px;
  border-radius: 10px;
  text-decoration: none;
  color: #64748b;
  transition: all 0.2s ease;
  position: relative;
  overflow: hidden;
}

.navLink:hover,
.mobileNavLink:hover {
  background-color: rgba(99, 102, 241, 0.08);
  color: #6366f1;
}

.activeLink {
  background: linear-gradient(135deg, rgba(99, 102, 241, 0.12), rgba(139, 92, 246, 0.12));
  color: #6366f1;
  font-weight: 500;
}

.activeLink::before {
  content: "";
  position: absolute;
  left: 0;
  top: 0;
  height: 100%;
  width: 4px;
  background: linear-gradient(to bottom, #97979b, #7b797e);
  border-radius: 0 4px 4px 0;
}

.iconWrapper {
  min-width: 40px;
  height: 40px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 20px;
  border-radius: 8px;
  position: relative;
  transition: all 0.2s ease;
}

.activeLink .iconWrapper {
  background-color: rgba(99, 102, 241, 0.15);
  color: #6366f1;
}

.iconPing {
  position: absolute;
  width: 100%;
  height: 100%;
  border-radius: 50%;
  background-color: rgba(99, 102, 241, 0.2);
  z-index: -1;
}

.linkText {
  margin-left: 12px;
  font-size: 15px;
  white-space: nowrap;
  font-weight: 500;
}

/* Menu item styles */
.menuWrapper,
.mobileMenuWrapper {
  margin-bottom: 5px;
}

.menuItem,
.mobileMenuItem {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 5px 5px;
  border-radius: 10px;
  cursor: pointer;
  color: #64748b;
  transition: all 0.2s ease;
  position: relative;
}

.menuItem:hover,
.mobileMenuItem:hover {
  background-color: rgba(99, 102, 241, 0.08);
  color: #6366f1;
}

.menuItem.active,
.mobileMenuItem.active {
  background: linear-gradient(135deg, rgba(99, 102, 241, 0.12), rgba(139, 92, 246, 0.12));
  color: #6366f1;
}

.menuItem.active::before,
.mobileMenuItem.active::before {
  content: "";
  position: absolute;
  left: 0;
  top: 0;
  height: 100%;
  width: 4px;
  background: linear-gradient(to bottom, #6b6b70, #6f6d74);
  border-radius: 0 4px 4px 0;
}

.menuItemContent {
  display: flex;
  align-items: center;
}

.arrowIcon {
  font-size: 14px;
  transition: transform 0.3s ease;
}

.arrowIcon.open {
  transform: rotate(-180deg);
}

/* Submenu styles */
.subMenu,
.mobileSubMenu {
  margin-left: 15px;
  margin-top: 5px;
  overflow: hidden;
}

.subMenuItem,
.mobileSubMenuItem {
  display: flex;
  align-items: center;
  padding: 10px 15px;

  display: flex;
  align-items: center;
  padding: 10px 15px;
  border-radius: 8px;
  text-decoration: none;
  color: #64748b;
  transition: all 0.2s ease;
  margin-bottom: 3px;
  font-size: 14px;
}

.subMenuItem:hover, .mobileSubMenuItem:hover {
  background-color: rgba(99, 102, 241, 0.05);
  color: #6366f1;
}

.activeSubItem {
  background-color: rgba(99, 102, 241, 0.08);
  color: #6366f1;
  font-weight: 500;
}

.subMenuIcon {
  min-width: 28px;
  height: 28px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 16px;
  border-radius: 6px;
  margin-right: 10px;
}

.activeSubItem .subMenuIcon {
  color: #6366f1;
}

.subMenuText {
  white-space: nowrap;
}

/* Sidebar footer */
.sidebarFooter {
  padding: 15px;
  border-top: 1px solid rgba(0, 0, 0, 0.06);
  margin-top: auto;
}

.userInfo {
  display: flex;
  flex-direction: column;
  align-items: center;
}

.userRole {
  font-size: 14px;
  font-weight: 500;
  color: #6366f1;
  background-color: rgba(99, 102, 241, 0.1);
  padding: 6px 12px;
  border-radius: 20px;
  text-align: center;

}

/* Main content */
.mainContent {
  flex: 1;
  padding: 20px;
  background-color: #f9fafb;
  min-height: 100vh;
  transition: all 0.3s ease;
}

/* Mobile specific styles */
.mobileNavLink {
  width: 100%;
  padding: 12px 10px;
  margin-bottom: 5px;
}

.mobileMenuItem {
  width: 100%;
  padding: 12px 10px;
}

.mobileSubMenu {
  margin-left: 0;
  padding-left: 15px;
  border-left: 2px solid rgba(99, 102, 241, 0.3);
}

.mobileSubMenuItem {
  padding: 10px;
}



.navLink:hover .iconWrapper,
.menuItem:hover .iconWrapper {
  animation: pulse 1.5s infinite;
}

/* Responsive styles */
@media (max-width: 768px) {
  .sidebar {
    display: none;
  }
  
  .mainContent {
    margin-left: 0;
    width: 100%;
  }
}

